-- ===========================================================================
-- DevJourney 365 — one-shot database setup
-- Run once in: Supabase Dashboard -> SQL Editor -> New query -> Run
-- Applies all migrations in order, seeds the curriculum, reloads the cache.
-- If tables already exist (e.g. core tables ran), their CREATE TABLE errors;
-- in that case run only the not-yet-applied files individually.
-- ===========================================================================

-- FROM 2026101001_create_core_tables.sql
-- =============================================================================
-- Migration: 20261010_01_create_core_tables
--
-- Authoritative schema for DevJourney 365.
--
-- Conventions:
--   * UUID primary keys everywhere.
--   * Timestamps are TIMESTAMPTZ and stored in UTC; formatting to the user's
--     timezone happens in the client (see locale-provider).
--   * Personal tables reference profiles(id), which references auth.users(id),
--     so deleting the auth user cascades through everything.
--   * Ownership is always expressed by an explicit `user_id` column so RLS can
--     be written as `user_id = auth.uid()` without joins.
--   * Uniqueness constraints exist wherever double-submission would corrupt
--     state (progress rows, points, achievements).
--
-- Row Level Security is enabled in migration 02. Do not skip it.
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- updated_at maintenance ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

-- =============================================================================
-- Identity
-- =============================================================================

CREATE TABLE public.profiles (
  id                 uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  username           text NOT NULL UNIQUE
                     CHECK (username ~ '^[a-zA-Z0-9_-]{3,30}$'),
  display_name       text,
  avatar_url         text,
  bio                text CHECK (char_length(bio) <= 500),
  learning_goals     text,
  preferred_language text CHECK (preferred_language IN ('en', 'ar')),
  -- Controls who can read this profile. 'private' = only the owner.
  profile_visibility text NOT NULL DEFAULT 'private'
                     CHECK (profile_visibility IN ('private', 'public', 'group')),
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now()
);

CREATE TRIGGER profiles_updated_at BEFORE UPDATE ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- =============================================================================
-- Curriculum (shared content — never per-user)
-- =============================================================================

CREATE TABLE public.curriculum_phases (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug          text NOT NULL UNIQUE,
  position      integer NOT NULL UNIQUE CHECK (position BETWEEN 1 AND 12),
  title_en      text NOT NULL,
  title_ar      text NOT NULL,
  summary_en    text NOT NULL,
  summary_ar    text NOT NULL,
  start_day     integer NOT NULL CHECK (start_day BETWEEN 1 AND 365),
  end_day       integer NOT NULL CHECK (end_day BETWEEN 1 AND 365),
  deliverable_en text NOT NULL,
  deliverable_ar text NOT NULL,
  CHECK (end_day >= start_day)
);

CREATE TABLE public.curriculum_days (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  day_number         integer NOT NULL UNIQUE CHECK (day_number BETWEEN 1 AND 365),
  phase_id           uuid NOT NULL REFERENCES public.curriculum_phases(id) ON DELETE RESTRICT,
  title_en           text NOT NULL,
  title_ar           text NOT NULL,
  topic              text NOT NULL,
  objective_en       text NOT NULL,
  objective_ar       text NOT NULL,
  lesson_en          text NOT NULL,
  lesson_ar          text NOT NULL,
  estimated_minutes  integer NOT NULL DEFAULT 90
                     CHECK (estimated_minutes BETWEEN 20 AND 300),
  exercise_en        text NOT NULL,
  exercise_ar        text NOT NULL,
  deliverable_en     text NOT NULL,
  deliverable_ar     text NOT NULL,
  criteria_en        text[] NOT NULL DEFAULT '{}',
  criteria_ar        text[] NOT NULL DEFAULT '{}',
  challenge_en       text,
  challenge_ar       text,
  prerequisites      integer[] NOT NULL DEFAULT '{}',
  kind               text NOT NULL DEFAULT 'lesson'
                     CHECK (kind IN ('lesson', 'practice', 'project', 'review', 'recovery')),
  created_at         timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT day_criteria_not_empty CHECK (array_length(criteria_en, 1) >= 1)
);

-- The roadmap day must fall inside its phase's range.
CREATE OR REPLACE FUNCTION public.curriculum_day_phase_range_check()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_start integer;
  v_end   integer;
BEGIN
  SELECT start_day, end_day INTO v_start, v_end
  FROM public.curriculum_phases WHERE id = NEW.phase_id;

  IF NEW.day_number < v_start OR NEW.day_number > v_end THEN
    RAISE EXCEPTION 'Day % is outside phase range %-%', NEW.day_number, v_start, v_end;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER curriculum_day_phase_range
  BEFORE INSERT OR UPDATE ON public.curriculum_days
  FOR EACH ROW EXECUTE FUNCTION public.curriculum_day_phase_range_check();

CREATE TABLE public.curriculum_tasks (
  id        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  day_id    uuid NOT NULL REFERENCES public.curriculum_days(id) ON DELETE CASCADE,
  position  integer NOT NULL CHECK (position > 0),
  title_en  text NOT NULL,
  title_ar  text NOT NULL,
  UNIQUE (day_id, position)
);

CREATE TABLE public.learning_resources (
  id        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  day_id    uuid REFERENCES public.curriculum_days(id) ON DELETE CASCADE,
  phase_id  uuid REFERENCES public.curriculum_phases(id) ON DELETE CASCADE,
  title     text NOT NULL,
  url       text NOT NULL CHECK (url ~ '^https://'),
  kind      text NOT NULL DEFAULT 'reference'
            CHECK (kind IN ('official', 'reference', 'arabic', 'paid', 'video')),
  note_en   text,
  note_ar   text,
  position  integer NOT NULL DEFAULT 0,
  -- A resource belongs to a day or a phase, never both or neither.
  CONSTRAINT resource_owner CHECK (num_nonnulls(day_id, phase_id) = 1)
);

-- =============================================================================
-- Personal learning
-- =============================================================================

CREATE TABLE public.user_day_progress (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  day_id       uuid NOT NULL REFERENCES public.curriculum_days(id) ON DELETE CASCADE,
  status       text NOT NULL DEFAULT 'not_started'
               CHECK (status IN ('not_started', 'in_progress', 'completed')),
  started_at   timestamptz,
  completed_at timestamptz,
  notes        text,
  learned      text,
  proof_url    text,
  rating       smallint CHECK (rating BETWEEN 1 AND 5),
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  -- One row per user per day: the structural guarantee against duplicate
  -- progress records and double point awards.
  UNIQUE (user_id, day_id),
  -- completed_at must be set iff status is completed.
  CONSTRAINT completion_timestamp_consistent CHECK (
    (status = 'completed' AND completed_at IS NOT NULL)
    OR (status <> 'completed')
  )
);

CREATE TRIGGER day_progress_updated_at BEFORE UPDATE ON public.user_day_progress
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TABLE public.user_task_progress (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  task_id      uuid NOT NULL REFERENCES public.curriculum_tasks(id) ON DELETE CASCADE,
  completed    boolean NOT NULL DEFAULT false,
  completed_at timestamptz,
  updated_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, task_id),
  CONSTRAINT task_completion_timestamp CHECK (
    (completed AND completed_at IS NOT NULL) OR (NOT completed)
  )
);

CREATE TRIGGER task_progress_updated_at BEFORE UPDATE ON public.user_task_progress
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- Notes are private by default and are never shared, even between group members.
CREATE TABLE public.user_notes (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  day_id     uuid REFERENCES public.curriculum_days(id) ON DELETE CASCADE,
  note_text  text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX user_notes_per_day ON public.user_notes (user_id, day_id)
  WHERE day_id IS NOT NULL;

CREATE TRIGGER user_notes_updated_at BEFORE UPDATE ON public.user_notes
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TABLE public.study_sessions (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id          uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  day_id           uuid REFERENCES public.curriculum_days(id) ON DELETE SET NULL,
  started_at       timestamptz NOT NULL,
  ended_at         timestamptz,
  -- Computed server-side by log_study_session(); never trusted from the client.
  duration_seconds integer NOT NULL DEFAULT 0 CHECK (duration_seconds >= 0),
  session_date     date NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')::date,
  created_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT session_end_after_start CHECK (ended_at IS NULL OR ended_at >= started_at)
);

CREATE TABLE public.weekly_reviews (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id        uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  iso_year       integer NOT NULL CHECK (iso_year BETWEEN 2020 AND 2100),
  iso_week       integer NOT NULL CHECK (iso_week BETWEEN 1 AND 53),
  strongest_topics  text NOT NULL DEFAULT '',
  revision_topics   text NOT NULL DEFAULT '',
  blockers           text NOT NULL DEFAULT '',
  next_week_goal     text NOT NULL DEFAULT '',
  planned_tasks      integer NOT NULL DEFAULT 0 CHECK (planned_tasks >= 0),
  completed_tasks    integer NOT NULL DEFAULT 0 CHECK (completed_tasks >= 0),
  self_assessment    text NOT NULL DEFAULT '',
  submitted_at    timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, iso_year, iso_week)
);

CREATE TRIGGER weekly_reviews_updated_at BEFORE UPDATE ON public.weekly_reviews
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TABLE public.monthly_reviews (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id            uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  year               integer NOT NULL CHECK (year BETWEEN 2020 AND 2100),
  month              integer NOT NULL CHECK (month BETWEEN 1 AND 12),
  projects_completed integer NOT NULL DEFAULT 0,
  study_minutes      integer NOT NULL DEFAULT 0,
  skills_practised   text NOT NULL DEFAULT '',
  revision_topics    text NOT NULL DEFAULT '',
  self_assessment    text NOT NULL DEFAULT '',
  biggest_win        text NOT NULL DEFAULT '',
  main_difficulty    text NOT NULL DEFAULT '',
  next_priorities    text NOT NULL DEFAULT '',
  submitted_at       timestamptz,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, year, month)
);

CREATE TRIGGER monthly_reviews_updated_at BEFORE UPDATE ON public.monthly_reviews
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- =============================================================================
-- Projects
-- =============================================================================

CREATE TABLE public.user_projects (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id          uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  name             text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 120),
  description      text,
  problem          text,
  stack            text[] NOT NULL DEFAULT '{}',
  status           text NOT NULL DEFAULT 'planned'
                   CHECK (status IN ('planned', 'in_progress', 'paused', 'completed')),
  start_date       date,
  target_date      date,
  repo_url         text CHECK (repo_url IS NULL OR repo_url ~ '^https://'),
  live_url         text CHECK (live_url IS NULL OR live_url ~ '^https://'),
  lessons_learned  text,
  challenges_faced text,
  -- Which roadmap phase this project came from, if any.
  phase_id         uuid REFERENCES public.curriculum_phases(id) ON DELETE SET NULL,
  visibility       text NOT NULL DEFAULT 'private'
                   CHECK (visibility IN ('private', 'group', 'public')),
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT target_after_start CHECK (target_date IS NULL OR start_date IS NULL OR target_date >= start_date)
);

CREATE TRIGGER user_projects_updated_at BEFORE UPDATE ON public.user_projects
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TABLE public.project_milestones (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id  uuid NOT NULL REFERENCES public.user_projects(id) ON DELETE CASCADE,
  title       text NOT NULL,
  completed   boolean NOT NULL DEFAULT false,
  due_date    date,
  position    integer NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now()
);

-- =============================================================================
-- Groups
-- =============================================================================

CREATE TABLE public.study_groups (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name           text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80),
  description    text,
  avatar_url     text,
  created_by     uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  visibility     text NOT NULL DEFAULT 'private'
                 CHECK (visibility IN ('private', 'group')),
  -- Master switch for whether members can see each other's progress at all.
  share_progress boolean NOT NULL DEFAULT true,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TRIGGER study_groups_updated_at BEFORE UPDATE ON public.study_groups
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TABLE public.study_group_members (
  id        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id  uuid NOT NULL REFERENCES public.study_groups(id) ON DELETE CASCADE,
  user_id   uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  role      text NOT NULL DEFAULT 'member'
            CHECK (role IN ('owner', 'admin', 'member')),
  joined_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (group_id, user_id)
);

CREATE TABLE public.group_invitations (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id   uuid NOT NULL REFERENCES public.study_groups(id) ON DELETE CASCADE,
  created_by uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  -- Random, unguessable code. The table is never readable by clients; codes
  -- are only ever redeemed through redeem_group_invitation().
  code       text NOT NULL UNIQUE,
  expires_at timestamptz,
  max_uses   integer CHECK (max_uses IS NULL OR max_uses > 0),
  uses       integer NOT NULL DEFAULT 0,
  used_at    timestamptz,
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.group_challenges (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id       uuid NOT NULL REFERENCES public.study_groups(id) ON DELETE CASCADE,
  created_by     uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  title          text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 120),
  description    text,
  rules          text,
  challenge_type text NOT NULL
                 CHECK (challenge_type IN (
                   'sessions',      -- N study sessions
                   'phase',         -- finish a curriculum phase
                   'project',       -- build and deploy something
                   'revision',      -- N revision sessions
                   'consistency'    -- N consecutive days
                 )),
  target_count   integer NOT NULL DEFAULT 7 CHECK (target_count > 0),
  starts_at      timestamptz NOT NULL DEFAULT now(),
  ends_at        timestamptz NOT NULL,
  bonus_points   integer NOT NULL DEFAULT 25 CHECK (bonus_points >= 0),
  created_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT challenge_window_valid CHECK (ends_at > starts_at)
);

CREATE TABLE public.challenge_participants (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  challenge_id  uuid NOT NULL REFERENCES public.group_challenges(id) ON DELETE CASCADE,
  user_id       uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  progress      integer NOT NULL DEFAULT 0 CHECK (progress >= 0),
  -- Set only by validate_challenge_progress(); clients cannot write it.
  completed     boolean NOT NULL DEFAULT false,
  completed_at  timestamptz,
  joined_at     timestamptz NOT NULL DEFAULT now(),
  UNIQUE (challenge_id, user_id)
);

-- =============================================================================
-- Achievements and points
-- =============================================================================

CREATE TABLE public.achievements (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code           text NOT NULL UNIQUE,
  title_en       text NOT NULL,
  title_ar       text NOT NULL,
  description_en text NOT NULL,
  description_ar text NOT NULL,
  icon           text,
  -- Verifiable condition, e.g. {"type": "days_completed", "threshold": 1}.
  criteria       jsonb NOT NULL,
  -- Optional: which roadmap phase this achievement belongs to.
  phase_position integer,
  created_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT achievement_criteria_valid CHECK (
    criteria ? 'type' AND criteria ? 'threshold'
  )
);

CREATE TABLE public.user_achievements (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id        uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  achievement_id uuid NOT NULL REFERENCES public.achievements(id) ON DELETE CASCADE,
  earned_at      timestamptz NOT NULL DEFAULT now(),
  -- Prevents the same achievement being awarded twice.
  UNIQUE (user_id, achievement_id)
);

-- Append-only ledger. No UPDATE/DELETE policy is ever granted: points are
-- immutable facts, not editable state.
CREATE TABLE public.point_ledger (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  reason     text NOT NULL
             CHECK (reason IN (
               'day_completed', 'exercise_completed', 'weekly_review',
               'challenge_completed', 'project_completed', 'bonus'
             )),
  points     integer NOT NULL CHECK (points <> 0),
  ref_type   text,
  ref_id     uuid,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- The anti-double-award guarantee.
--
-- A plain UNIQUE(user_id, reason, ref_type, ref_id) would NOT work here: in
-- Postgres NULLs are distinct from each other, so a ledger row with a NULL
-- ref_id could be inserted any number of times. COALESCE gives NULL a single
-- sentinel value so the constraint actually bites.
CREATE UNIQUE INDEX point_ledger_no_double_award ON public.point_ledger (
  user_id,
  reason,
  coalesce(ref_type, ''),
  coalesce(ref_id, '00000000-0000-0000-0000-000000000000'::uuid)
);

CREATE INDEX point_ledger_user_created ON public.point_ledger (user_id, created_at DESC);

-- =============================================================================
-- Privacy, notifications, activity
-- =============================================================================

CREATE TABLE public.user_privacy_settings (
  id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id                uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE,
  share_progress         boolean NOT NULL DEFAULT true,
  share_streak           boolean NOT NULL DEFAULT true,
  share_achievements     boolean NOT NULL DEFAULT true,
  -- Off by default and, regardless of this flag, notes are never readable by
  -- other members under the current RLS policies. Kept for a future explicit
  -- "share this note" feature.
  share_notes            boolean NOT NULL DEFAULT false,
  hidden_from_leaderboard boolean NOT NULL DEFAULT false,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now()
);

CREATE TRIGGER privacy_settings_updated_at BEFORE UPDATE ON public.user_privacy_settings
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TABLE public.notification_preferences (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id          uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE,
  daily_reminders  boolean NOT NULL DEFAULT false,
  reminder_time    time,
  group_activity   boolean NOT NULL DEFAULT true,
  challenge_updates boolean NOT NULL DEFAULT true,
  timezone         text NOT NULL DEFAULT 'UTC',
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);

CREATE TRIGGER notification_preferences_updated_at
  BEFORE UPDATE ON public.notification_preferences
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TABLE public.activity_events (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  group_id   uuid REFERENCES public.study_groups(id) ON DELETE SET NULL,
  type       text NOT NULL
             CHECK (type IN (
               'progress_update', 'achievement_earned', 'challenge_completed',
               'challenge_joined', 'project_completed', 'group_joined',
               'group_left', 'encouragement'
             )),
  related_id uuid,
  message    text CHECK (char_length(message) <= 280),
  created_at timestamptz NOT NULL DEFAULT now()
);

-- =============================================================================
-- Indexes for the query patterns the app actually uses
-- =============================================================================
CREATE INDEX curriculum_days_phase      ON public.curriculum_days (phase_id, day_number);
CREATE INDEX curriculum_tasks_day       ON public.curriculum_tasks (day_id, position);
CREATE INDEX learning_resources_day    ON public.learning_resources (day_id);

CREATE INDEX user_day_progress_user    ON public.user_day_progress (user_id, day_id);
CREATE INDEX user_day_progress_status  ON public.user_day_progress (user_id, status);
CREATE INDEX user_task_progress_user   ON public.user_task_progress (user_id);
CREATE INDEX user_notes_user          ON public.user_notes (user_id);
CREATE INDEX study_sessions_user_date  ON public.study_sessions (user_id, session_date DESC);
CREATE INDEX weekly_reviews_user       ON public.weekly_reviews (user_id, iso_year DESC, iso_week DESC);
CREATE INDEX monthly_reviews_user      ON public.monthly_reviews (user_id, year DESC, month DESC);

CREATE INDEX user_projects_user        ON public.user_projects (user_id, status);
CREATE INDEX user_projects_visibility  ON public.user_projects (visibility)
  WHERE visibility = 'public';
CREATE INDEX project_milestones_project ON public.project_milestones (project_id);

CREATE INDEX group_members_group       ON public.study_group_members (group_id);
CREATE INDEX group_members_user        ON public.study_group_members (user_id);
CREATE INDEX invitations_group         ON public.group_invitations (group_id);
CREATE INDEX invitations_active_code   ON public.group_invitations (code)
  WHERE revoked_at IS NULL;
CREATE INDEX challenges_group          ON public.group_challenges (group_id, ends_at);
CREATE INDEX challenge_participants_user ON public.challenge_participants (user_id);

CREATE INDEX user_achievements_user    ON public.user_achievements (user_id, earned_at DESC);
CREATE INDEX activity_events_user      ON public.activity_events (user_id, created_at DESC);
CREATE INDEX activity_events_group     ON public.activity_events (group_id, created_at DESC);

-- FROM 2026101002_row_level_security.sql
-- =============================================================================
-- Migration: 20261010_02_row_level_security
--
-- CRITICAL: the previous migration created every table WITHOUT Row Level
-- Security. With RLS disabled, Supabase's PostgREST layer exposes every row of
-- every table to any caller holding the anon key — any signed-in user could
-- read every other user's private notes, progress and projects.
--
-- This migration enables RLS on every table and writes explicit policies.
--
-- Design rules used throughout:
--   1. Authorization is derived from auth.uid() ONLY. Never from
--      user-editable profile metadata (display_name, username, etc.).
--   2. UPDATE policies check BOTH `USING` (who can see the row) and
--      `WITH CHECK` (what the row is allowed to become). Without WITH CHECK a
--      user could move their own row to another owner_id.
--   3. Private data is never world-readable, even to authenticated users.
--   4. Group access requires verified membership, checked in the database.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Helper functions (SECURITY DEFINER so they can bypass RLS on profiles when
-- resolving membership, without granting that power to clients).
-- -----------------------------------------------------------------------------

-- Is the given user a member of the given group, optionally at a minimum role?
CREATE OR REPLACE FUNCTION public.is_group_member(p_group_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.study_group_members m
    WHERE m.group_id = p_group_id AND m.user_id = p_user_id
  );
$$;

CREATE OR REPLACE FUNCTION public.has_group_role(
  p_group_id uuid,
  p_user_id uuid,
  p_roles text[]
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.study_group_members m
    WHERE m.group_id = p_group_id
      AND m.user_id = p_user_id
      AND m.role = ANY (p_roles)
  );
$$;

-- Is the user a member of the group that owns this challenge?
CREATE OR REPLACE FUNCTION public.is_challenge_member(p_challenge_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT public.is_group_member(c.group_id, p_user_id)
  FROM public.group_challenges c
  WHERE c.id = p_challenge_id;
$$;

-- Does the target user share their progress/achievements with this viewer?
CREATE OR REPLACE FUNCTION public.shares_learning_with(p_owner_id uuid, p_viewer_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_privacy_settings s
    WHERE s.user_id = p_owner_id
      AND s.share_progress = true
      AND EXISTS (
        SELECT 1
        FROM public.study_group_members viewer
        JOIN public.study_group_members owner
          ON owner.group_id = viewer.group_id
        WHERE viewer.user_id = p_viewer_id
          AND owner.user_id = p_owner_id
      )
  );
$$;

-- -----------------------------------------------------------------------------
-- 1. Enable RLS on EVERY table.
--
-- This list must stay in sync with migration 01. A table missing here is fully
-- exposed to any caller holding the anon key.
-- -----------------------------------------------------------------------------
DO $$
DECLARE
  t text;
  missing text[] := ARRAY[]::text[];
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'profiles',
    'curriculum_phases',
    'curriculum_days',
    'curriculum_tasks',
    'learning_resources',
    'user_day_progress',
    'user_task_progress',
    'user_notes',
    'study_sessions',
    'weekly_reviews',
    'monthly_reviews',
    'user_projects',
    'project_milestones',
    'study_groups',
    'study_group_members',
    'group_invitations',
    'group_challenges',
    'challenge_participants',
    'achievements',
    'user_achievements',
    'point_ledger',
    'user_privacy_settings',
    'notification_preferences',
    'activity_events'
  ]
  LOOP
    IF to_regclass('public.' || t) IS NULL THEN
      missing := array_append(missing, t);
    ELSE
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    END IF;
  END LOOP;

  IF array_length(missing, 1) > 0 THEN
    RAISE EXCEPTION 'Expected tables are missing: %', missing;
  END IF;
END $$;

-- -----------------------------------------------------------------------------
-- 2. profiles
--
-- A profile is split conceptually in two:
--   * identity columns (id, username, created_at) — needed to render member
--     lists and is not sensitive.
--   * private columns (bio, learning_goals) — owner only.
--
-- Postgres RLS cannot do column-level filtering inside a SELECT policy, so we
-- expose a public-safe view instead of the raw table.
-- -----------------------------------------------------------------------------

-- Public-safe projection. Reading this never exposes bio or learning_goals.
CREATE OR REPLACE VIEW public.profiles_public
WITH (security_invoker = false)
AS
  SELECT
    p.id,
    p.username,
    p.display_name,
    p.avatar_url,
    p.profile_visibility,
    p.created_at,
    coalesce(s.share_achievements, false) AS shares_achievements,
    coalesce(s.share_streak, false)      AS shares_streak,
    coalesce(s.hidden_from_leaderboard, false) AS hidden_from_leaderboard
  FROM public.profiles p
  LEFT JOIN public.user_privacy_settings s ON s.user_id = p.id
  WHERE p.profile_visibility IN ('public', 'group')
     OR p.id = auth.uid()
     OR public.shares_learning_with(p.id, auth.uid());

GRANT SELECT ON public.profiles_public TO authenticated;

-- Owner-only access to their own full profile row.
CREATE POLICY profiles_select_own ON public.profiles
  FOR SELECT USING (id = auth.uid());

CREATE POLICY profiles_update_own ON public.profiles
  FOR UPDATE
  USING (id = auth.uid())
  -- A user must not be able to change their own id.
  WITH CHECK (id = auth.uid());

CREATE POLICY profiles_insert_self ON public.profiles
  FOR INSERT WITH CHECK (id = auth.uid());

-- Delete is intentionally NOT granted here: account deletion goes through the
-- SECURITY DEFINER function below so related rows are cleaned up atomically.

-- -----------------------------------------------------------------------------
-- 3. Curriculum — public read, never client-writable.
--    The roadmap is shared content, not per-user data.
-- -----------------------------------------------------------------------------
CREATE POLICY curriculum_read ON public.curriculum_days
  FOR SELECT
  TO anon, authenticated
  USING (true);

-- No INSERT/UPDATE/DELETE policies => writes are denied for all client roles.
-- The seed script runs as the migration owner, which bypasses RLS.

-- Phases, tasks and resources are shared curriculum content: readable by
-- anyone (including anonymous visitors), writable only by the migration owner.
CREATE POLICY curriculum_phases_read ON public.curriculum_phases
  FOR SELECT TO anon, authenticated USING (true);

CREATE POLICY curriculum_tasks_read ON public.curriculum_tasks
  FOR SELECT TO anon, authenticated USING (true);

CREATE POLICY curriculum_resources_read ON public.learning_resources
  FOR SELECT TO anon, authenticated USING (true);

-- -----------------------------------------------------------------------------
-- 3b. Project milestones follow their parent project's visibility.
-- -----------------------------------------------------------------------------
CREATE POLICY milestones_select_visible ON public.project_milestones
  FOR SELECT USING (
    EXISTS (
      SELECT 1 FROM public.user_projects p
      WHERE p.id = project_milestones.project_id
        AND (
          p.user_id = auth.uid()
          OR p.visibility = 'public'
          OR (p.visibility = 'group' AND EXISTS (
                SELECT 1
                FROM public.study_group_members mine
                JOIN public.study_group_members theirs ON theirs.group_id = mine.group_id
                WHERE mine.user_id = auth.uid() AND theirs.user_id = p.user_id
             ))
        )
    )
  );

CREATE POLICY milestones_owner_all ON public.project_milestones
  FOR ALL
  USING (EXISTS (
    SELECT 1 FROM public.user_projects p
    WHERE p.id = project_milestones.project_id AND p.user_id = auth.uid()
  ))
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.user_projects p
    WHERE p.id = project_milestones.project_id AND p.user_id = auth.uid()
  ));

-- -----------------------------------------------------------------------------
-- 3c. Point ledger.
--
-- Own points are readable so the client can show a total. No INSERT policy
-- exists for any client role: points are only ever written by the SECURITY
-- DEFINER awarding functions. There is also no UPDATE/DELETE policy, which
-- makes the ledger append-only from the client's perspective.
-- -----------------------------------------------------------------------------
CREATE POLICY point_ledger_select_own ON public.point_ledger
  FOR SELECT USING (user_id = auth.uid());

-- -----------------------------------------------------------------------------
-- 3d. Notification preferences — owner only.
-- -----------------------------------------------------------------------------
CREATE POLICY notification_preferences_owner_all ON public.notification_preferences
  FOR ALL
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

-- -----------------------------------------------------------------------------
-- 4. Personal learning data — strictly owner-only.
-- -----------------------------------------------------------------------------

-- Day progress
CREATE POLICY day_progress_owner_all ON public.user_day_progress
  FOR ALL
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

-- Task progress
CREATE POLICY task_progress_owner_all ON public.user_task_progress
  FOR ALL
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

-- Notes: NEVER shared. There is deliberately no policy granting other users
-- read access, regardless of their privacy settings.
CREATE POLICY notes_owner_all ON public.user_notes
  FOR ALL
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

-- Study sessions
CREATE POLICY sessions_owner_all ON public.study_sessions
  FOR ALL
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

-- Reviews
CREATE POLICY weekly_reviews_owner_all ON public.weekly_reviews
  FOR ALL
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

CREATE POLICY monthly_reviews_owner_all ON public.monthly_reviews
  FOR ALL
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

-- Privacy settings: owner only.
CREATE POLICY privacy_settings_owner_all ON public.user_privacy_settings
  FOR ALL
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

-- -----------------------------------------------------------------------------
-- 5. Projects — owner writes; reads depend on the project's visibility.
-- -----------------------------------------------------------------------------
CREATE POLICY projects_select_visible ON public.user_projects
  FOR SELECT USING (
    user_id = auth.uid()
    OR visibility = 'public'
    OR (
      visibility = 'group'
      AND EXISTS (
        SELECT 1
        FROM public.study_group_members mine
        JOIN public.study_group_members theirs
          ON theirs.group_id = mine.group_id
        WHERE mine.user_id = auth.uid()
          AND theirs.user_id = user_projects.user_id
      )
    )
  );

CREATE POLICY projects_insert_own ON public.user_projects
  FOR INSERT WITH CHECK (user_id = auth.uid());

CREATE POLICY projects_update_own ON public.user_projects
  FOR UPDATE
  USING (user_id = auth.uid())
  -- WITH CHECK stops a user re-assigning the project to somebody else.
  WITH CHECK (user_id = auth.uid());

CREATE POLICY projects_delete_own ON public.user_projects
  FOR DELETE USING (user_id = auth.uid());

-- -----------------------------------------------------------------------------
-- 6. Groups and membership
-- -----------------------------------------------------------------------------
CREATE POLICY groups_select_members ON public.study_groups
  FOR SELECT
  USING (
    created_by = auth.uid()
    OR public.is_group_member(id, auth.uid())
  );

CREATE POLICY groups_insert_self ON public.study_groups
  FOR INSERT WITH CHECK (created_by = auth.uid());

-- Only an owner/admin may edit group settings.
CREATE POLICY groups_update_admins ON public.study_groups
  FOR UPDATE
  USING (public.has_group_role(id, auth.uid(), ARRAY['owner', 'admin']::text[]))
  WITH CHECK (public.has_group_role(id, auth.uid(), ARRAY['owner', 'admin']::text[]));

-- Membership list visible to fellow members.
CREATE POLICY members_select_group ON public.study_group_members
  FOR SELECT USING (public.is_group_member(group_id, auth.uid()));

-- Joining: a user may insert their own member row, but ONLY with role
-- 'member'. This is what stops a user granting themselves 'owner'.
CREATE POLICY members_insert_self_member_only ON public.study_group_members
  FOR INSERT
  WITH CHECK (
    user_id = auth.uid()
    AND role = 'member'
  );

-- Changing someone else's role, or promoting yourself, requires owner/admin.
CREATE POLICY members_update_admins ON public.study_group_members
  FOR UPDATE
  USING (public.has_group_role(group_id, auth.uid(), ARRAY['owner', 'admin']::text[]))
  WITH CHECK (public.has_group_role(group_id, auth.uid(), ARRAY['owner', 'admin']::text[]));

-- Leaving a group is always allowed for your own row.
CREATE POLICY members_delete_self_or_admin ON public.study_group_members
  FOR DELETE USING (
    user_id = auth.uid()
    OR public.has_group_role(group_id, auth.uid(), ARRAY['owner', 'admin']::text[])
  );

-- Invitations: only admins can read or manage them. The invitation *code* must
-- not be enumerable, so there is intentionally no policy allowing anonymous
-- lookup by code — redemption happens through the SECURITY DEFINER function.
CREATE POLICY invitations_admin_all ON public.group_invitations
  FOR ALL
  USING (public.has_group_role(group_id, auth.uid(), ARRAY['owner', 'admin']::text[]))
  WITH CHECK (public.has_group_role(group_id, auth.uid(), ARRAY['owner', 'admin']::text[]));

-- -----------------------------------------------------------------------------
-- 7. Challenges
-- -----------------------------------------------------------------------------
CREATE POLICY challenges_select_members ON public.group_challenges
  FOR SELECT USING (public.is_group_member(group_id, auth.uid()));

CREATE POLICY challenges_insert_admins ON public.group_challenges
  FOR INSERT
  WITH CHECK (
    created_by = auth.uid()
    AND public.has_group_role(group_id, auth.uid(), ARRAY['owner', 'admin']::text[])
  );

CREATE POLICY challenges_update_admins ON public.group_challenges
  FOR UPDATE
  USING (public.has_group_role(group_id, auth.uid(), ARRAY['owner', 'admin']::text[]))
  WITH CHECK (public.has_group_role(group_id, auth.uid(), ARRAY['owner', 'admin']::text[]));

CREATE POLICY challenges_delete_creator_or_admin ON public.group_challenges
  FOR DELETE USING (
    created_by = auth.uid()
    OR public.has_group_role(group_id, auth.uid(), ARRAY['owner', 'admin']::text[])
  );

-- Participants can read the roster of their own group, and can only ever write
-- their OWN participation row (no self-awarding of completion or points).
-- Progress is only visible when the user has opted in to sharing.
CREATE POLICY participants_select_group ON public.challenge_participants
  FOR SELECT USING (
    public.is_challenge_member(challenge_id, auth.uid())
    AND EXISTS (
      SELECT 1 FROM public.user_privacy_settings s
      WHERE s.user_id = challenge_participants.user_id
        AND s.share_progress = true
    )
  );

CREATE POLICY participants_insert_self ON public.challenge_participants
  FOR INSERT WITH CHECK (user_id = auth.uid());

CREATE POLICY participants_update_self_no_progress ON public.challenge_participants
  FOR UPDATE
  USING (user_id = auth.uid())
  -- Completion is awarded by the validation function, never by the client, so
  -- a member cannot simply flip `completed` to true.
  WITH CHECK (
    user_id = auth.uid()
    AND completed = false
    AND completed_at IS NULL
  );

CREATE POLICY participants_delete_self ON public.challenge_participants
  FOR DELETE USING (user_id = auth.uid());

-- -----------------------------------------------------------------------------
-- 8. Achievements and points
-- -----------------------------------------------------------------------------
-- The achievement catalogue is public reference data.
CREATE POLICY achievements_read_all ON public.achievements
  FOR SELECT USING (true);

-- A user may read their own earned achievements, and those of group members
-- who have opted in to sharing.
CREATE POLICY user_achievements_select ON public.user_achievements
  FOR SELECT USING (
    user_id = auth.uid()
    OR EXISTS (
      SELECT 1 FROM public.user_privacy_settings s
      WHERE s.user_id = user_achievements.user_id AND s.share_achievements = true
    )
  );

-- There is deliberately NO insert policy on user_achievements. Achievements are
-- awarded only by the SECURITY DEFINER function below, which re-verifies the
-- underlying condition. A client cannot simply insert a row to claim one.
--
-- Similarly there is no INSERT/UPDATE policy on a point ledger table: points
-- are awarded server-side only.

-- -----------------------------------------------------------------------------
-- 9. Activity feed
-- -----------------------------------------------------------------------------
CREATE POLICY activity_select_group_or_own ON public.activity_events
  FOR SELECT USING (
    user_id = auth.uid()
    OR (group_id IS NOT NULL AND public.is_group_member(group_id, auth.uid()))
  );

CREATE POLICY activity_insert_self ON public.activity_events
  FOR INSERT WITH CHECK (user_id = auth.uid());

-- -----------------------------------------------------------------------------
-- 10. SECURITY DEFINER functions
--
-- These perform multi-step, security-sensitive work atomically. SECURITY
-- DEFINER lets them read/write rows the caller cannot, so each one must
-- re-verify authorization internally and validate its own inputs.
-- -----------------------------------------------------------------------------

-- Create a profile row for a brand-new auth user.
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_username text;
  v_display  text;
BEGIN
  v_username := coalesce(new.raw_user_meta_data ->> 'username', split_part(new.email, '@', 1));
  -- Guarantee uniqueness even when two users pick the same display username.
  v_username := v_username || '-' || substr(replace(new.id::text, '-', ''), 1, 6);

  v_display := coalesce(new.raw_user_meta_data ->> 'display_name', v_username);

  INSERT INTO public.profiles (id, username, display_name, profile_visibility)
  VALUES (new.id, v_username, v_display, 'private')
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.user_privacy_settings (user_id) VALUES (new.id)
  ON CONFLICT (user_id) DO NOTHING;

  RETURN new;
END;
$$;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- Redeem an invitation code.
--
-- Runs as SECURITY DEFINER so the code can be matched without granting anyone
-- read access to the invitations table. Checks expiry, revocation and whether
-- the group is already full, and ALWAYS joins as role 'member' — an invitation
-- can never grant elevated privileges.
CREATE OR REPLACE FUNCTION public.redeem_group_invitation(p_code text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_inv public.group_invitations%ROWTYPE;
  v_uid uuid := auth.uid();
  v_group uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_inv
  FROM public.group_invitations
  WHERE code = p_code
    AND revoked_at IS NULL
    AND (expires_at IS NULL OR expires_at > now())
    AND (max_uses IS NULL OR uses < max_uses)
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid or expired invitation code' USING ERRCODE = '22023';
  END IF;

  IF v_inv.expires_at IS NOT NULL AND v_inv.expires_at < now() THEN
    RAISE EXCEPTION 'Invitation code has expired' USING ERRCODE = '22023';
  END IF;

  v_group := v_inv.group_id;

  UPDATE public.group_invitations
  SET uses = coalesce(uses, 0) + 1,
      used_at = coalesce(used_at, now())
  WHERE id = v_inv.id;

  INSERT INTO public.study_group_members (group_id, user_id, role)
  VALUES (v_group, v_uid, 'member')
  ON CONFLICT (group_id, user_id) DO NOTHING;

  RETURN v_group;
END;
$$;

GRANT EXECUTE ON FUNCTION public.redeem_group_invitation(text) TO authenticated;

-- Record study time.
--
-- The client sends started_at/ended_at; the server computes duration_seconds so
-- a client cannot claim an arbitrary number of minutes (and therefore points).
-- Rejects absurd durations.
CREATE OR REPLACE FUNCTION public.log_study_session(
  p_started_at timestamptz,
  p_ended_at   timestamptz,
  p_day_id     uuid DEFAULT NULL
)
RETURNS public.study_sessions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_seconds integer;
  v_row public.study_sessions%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_ended_at <= p_started_at THEN
    RAISE EXCEPTION 'Session end must be after start' USING ERRCODE = '22023';
  END IF;

  v_seconds := floor(extract(epoch FROM (p_ended_at - p_started_at)))::integer;

  -- Cap a single session at 8 hours to bound what the leaderboard can be fed.
  IF v_seconds > 28800 THEN
    RAISE EXCEPTION 'Session duration exceeds the 8 hour limit' USING ERRCODE = '22023';
  END IF;
  IF v_seconds < 30 THEN
    RAISE EXCEPTION 'Session too short to record' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.study_sessions (
    user_id, day_id, started_at, ended_at, duration_seconds, session_date
  )
  VALUES (
    v_uid,
    p_day_id,
    p_started_at,
    p_ended_at,
    v_seconds,
    (p_started_at AT TIME ZONE 'UTC')::date
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;

GRANT EXECUTE ON FUNCTION public.log_study_session(timestamptz, timestamptz, uuid) TO authenticated;

-- Complete a curriculum day, awarding points exactly once.
--
-- The UNIQUE constraint on user_day_progress(user_id, day_id) plus the
-- "was it already completed" check below mean repeated calls cannot re-award.
CREATE OR REPLACE FUNCTION public.complete_curriculum_day(
  p_day_id   uuid,
  p_learned   text DEFAULT NULL,
  p_proof_url text DEFAULT NULL
)
RETURNS public.user_day_progress
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.user_day_progress%ROWTYPE;
  v_already boolean;
  v_day_number integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT day_number INTO v_day_number
  FROM public.curriculum_days WHERE id = p_day_id;

  IF v_day_number IS NULL THEN
    RAISE EXCEPTION 'Unknown curriculum day' USING ERRCODE = '22023';
  END IF;

  SELECT completed INTO v_already
  FROM public.user_day_progress
  WHERE user_id = v_uid AND day_id = p_day_id;

  INSERT INTO public.user_day_progress AS udp
    (user_id, day_id, status, started_at, completed_at, learned, proof_url)
  VALUES (v_uid, p_day_id, 'completed', now(), now(), p_learned, p_proof_url)
  ON CONFLICT (user_id, day_id) DO UPDATE
    SET status = 'completed',
        completed_at = now(),
        learned = coalesce(excluded.learned, udp.learned),
        proof_url = coalesce(excluded.proof_url, udp.proof_url),
        updated_at = now()
  RETURNING * INTO v_row;

  -- Only award on the first completion.
  IF v_already IS NOT TRUE THEN
    INSERT INTO public.point_ledger (user_id, reason, points, ref_type, ref_id)
    VALUES (v_uid, 'day_completed', 10, 'curriculum_day', p_day_id);
  END IF;

  RETURN v_row;
END;
$$;

GRANT EXECUTE ON FUNCTION public.complete_curriculum_day(uuid, text, text) TO authenticated;

-- Self-service account deletion: removes the caller's auth user, which cascades
-- to every table that references auth.users(id).
CREATE OR REPLACE FUNCTION public.delete_my_account()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  DELETE FROM auth.users WHERE id = v_uid;
END;
$$;

GRANT EXECUTE ON FUNCTION public.delete_my_account() TO authenticated;

-- FROM 2026101003_group_management.sql
-- =============================================================================
-- Migration: 20261010_03_group_management
--
-- Sensitive group operations are implemented as SECURITY DEFINER functions
-- rather than direct client writes, because they need logic that RLS policies
-- cannot express:
--
--   * invitation codes must be generated by the database (gen_random_bytes),
--     not by the browser, or they are guessable;
--   * a group must never be left without an owner;
--   * role changes must not be possible for a plain member.
--
-- Every function re-verifies the caller's own privileges internally. SECURITY
-- DEFINER bypasses RLS, so a function that forgot to check its caller would
-- be a privilege-escalation hole.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Invitations
-- -----------------------------------------------------------------------------

-- Create an invitation for a group the caller owns or administers.
CREATE OR REPLACE FUNCTION public.create_group_invitation(
  p_group_id    uuid,
  p_expires_days integer DEFAULT 7,
  p_max_uses    integer  DEFAULT NULL
)
RETURNS public.group_invitations
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_code    text;
  v_row     public.group_invitations%ROWTYPE;
  v_attempt int := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_group_role(p_group_id, v_uid, ARRAY['owner', 'admin']::text[]) THEN
    RAISE EXCEPTION 'Only a group owner or admin can create invitations'
      USING ERRCODE = '42501';
  END IF;

  IF p_max_uses IS NOT NULL AND p_max_uses < 1 THEN
    RAISE EXCEPTION 'max_uses must be at least 1' USING ERRCODE = '22023';
  END IF;

  IF p_expires_days IS NOT NULL AND (p_expires_days < 1 OR p_expires_days > 365) THEN
    RAISE EXCEPTION 'expires_days must be between 1 and 365' USING ERRCODE = '22023';
  END IF;

  -- 12 random bytes -> 24 hex characters (96 bits of entropy). Generated here,
  -- never in the client, so the code cannot be predicted or brute-forced from
  -- a guessable seed. Retry on the (astronomically unlikely) collision.
  LOOP
    v_code := encode(gen_random_bytes(12), 'hex');
    v_attempt := v_attempt + 1;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.group_invitations WHERE code = v_code);
    IF v_attempt > 5 THEN
      RAISE EXCEPTION 'Could not generate a unique invitation code' USING ERRCODE = '40001';
    END IF;
  END LOOP;

  INSERT INTO public.group_invitations
    (group_id, created_by, code, expires_at, max_uses)
  VALUES (
    p_group_id,
    v_uid,
    v_code,
    CASE WHEN p_expires_days IS NULL THEN NULL
         ELSE now() + make_interval(days => p_expires_days) END,
    p_max_uses
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_group_invitation(uuid, integer, integer)
  TO authenticated;

-- Revoke an existing invitation. The code stops working immediately; the row is
-- kept so the admin can see that it existed and when it was revoked.
CREATE OR REPLACE FUNCTION public.revoke_group_invitation(p_invitation_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_group uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT group_id INTO v_group
  FROM public.group_invitations
  WHERE id = p_invitation_id;

  IF v_group IS NULL THEN
    RAISE EXCEPTION 'Invitation not found' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_group_role(v_group, v_uid, ARRAY['owner', 'admin']::text[]) THEN
    RAISE EXCEPTION 'Only a group owner or admin can revoke invitations'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.group_invitations
  SET revoked_at = COALESCE(revoked_at, now())
  WHERE id = p_invitation_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.revoke_group_invitation(uuid) TO authenticated;

-- -----------------------------------------------------------------------------
-- Membership
-- -----------------------------------------------------------------------------

-- Count the owners in a group. Used to refuse any change that would leave the
-- group ownerless.
CREATE OR REPLACE FUNCTION public.owner_count(p_group_id uuid)
RETURNS integer
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT count(*)::integer
  FROM public.study_group_members
  WHERE group_id = p_group_id AND role = 'owner';
$$;

-- Leave a group yourself.
--
-- An owner cannot simply leave and orphan the group: the caller must transfer
-- ownership or promote someone first. We surface a clear error instead of
-- silently demoting someone.
CREATE OR REPLACE FUNCTION public.leave_group(p_group_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_role   text;
  v_owners integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_role
  FROM public.study_group_members
  WHERE group_id = p_group_id AND user_id = v_uid;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'You are not a member of this group' USING ERRCODE = '22023';
  END IF;

  IF v_role = 'owner' THEN
    v_owners := public.owner_count(p_group_id);
    IF v_owners <= 1 THEN
      RAISE EXCEPTION 'You are the only owner. Transfer ownership before leaving.'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  DELETE FROM public.study_group_members
  WHERE group_id = p_group_id AND user_id = v_uid;
END;
$$;

GRANT EXECUTE ON FUNCTION public.leave_group(uuid) TO authenticated;

-- Change a member's role. Owners only: an admin must not be able to promote
-- someone to owner, or demote another owner.
CREATE OR REPLACE FUNCTION public.change_member_role(
  p_group_id uuid,
  p_user_id  uuid,
  p_role     text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_owners  integer;
  v_current text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_role NOT IN ('owner', 'admin', 'member') THEN
    RAISE EXCEPTION 'Invalid role' USING ERRCODE = '22023';
  END IF;

  IF p_user_id = v_uid THEN
    RAISE EXCEPTION 'You cannot change your own role' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_group_role(p_group_id, v_uid, ARRAY['owner']::text[]) THEN
    RAISE EXCEPTION 'Only a group owner can change roles' USING ERRCODE = '42501';
  END IF;

  SELECT role INTO v_current
  FROM public.study_group_members
  WHERE group_id = p_group_id AND user_id = p_user_id;

  IF v_current IS NULL THEN
    RAISE EXCEPTION 'That person is not a member of this group' USING ERRCODE = '22023';
  END IF;

  -- Never leave the group without an owner.
  IF v_current = 'owner' AND p_role <> 'owner' THEN
    v_owners := public.owner_count(p_group_id);
    IF v_owners <= 1 THEN
      RAISE EXCEPTION 'A group must keep at least one owner. Promote someone else first.'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  UPDATE public.study_group_members
  SET role = p_role
  WHERE group_id = p_group_id AND user_id = p_user_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.change_member_role(uuid, uuid, text) TO authenticated;

-- Remove someone from a group. Owners and admins may remove anyone except the
-- last owner; members may remove only themselves.
CREATE OR REPLACE FUNCTION public.remove_group_member(
  p_group_id uuid,
  p_user_id  uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_role    text;
  v_is_self boolean;
  v_owners  integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  v_is_self := (p_user_id = v_uid);

  IF NOT v_is_self
     AND NOT public.has_group_role(p_group_id, v_uid, ARRAY['owner', 'admin']::text[]) THEN
    RAISE EXCEPTION 'Only an owner or admin can remove other members' USING ERRCODE = '42501';
  END IF;

  SELECT role INTO v_role
  FROM public.study_group_members
  WHERE group_id = p_group_id AND user_id = p_user_id;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'That person is not a member of this group' USING ERRCODE = '22023';
  END IF;

  -- An admin cannot remove an owner.
  IF NOT v_is_self
     AND v_role = 'owner'
     AND NOT public.has_group_role(p_group_id, v_uid, ARRAY['owner']::text[]) THEN
    RAISE EXCEPTION 'Only an owner can remove another owner' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'owner' THEN
    v_owners := public.owner_count(p_group_id);
    IF v_owners <= 1 THEN
      RAISE EXCEPTION 'A group must keep at least one owner.' USING ERRCODE = '22023';
    END IF;
  END IF;

  DELETE FROM public.study_group_members
  WHERE group_id = p_group_id AND user_id = p_user_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.remove_group_member(uuid, uuid) TO authenticated;

-- -----------------------------------------------------------------------------
-- Group creation
--
-- Creating a group inserts the group and its owner membership row atomically.
-- A partial create (group with no owner) is not reachable.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_study_group(
  p_name        text,
  p_description text DEFAULT NULL,
  p_visibility  text DEFAULT 'private'
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_group_id uuid;
  v_name     text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  v_name := btrim(p_name);
  IF v_name IS NULL OR char_length(v_name) < 1 OR char_length(v_name) > 80 THEN
    RAISE EXCEPTION 'Group name must be 1-80 characters' USING ERRCODE = '22023';
  END IF;

  IF p_visibility NOT IN ('private', 'group') THEN
    RAISE EXCEPTION 'Invalid visibility' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.study_groups (name, description, created_by, visibility)
  VALUES (v_name, NULLIF(btrim(coalesce(p_description, '')), ''), v_uid, p_visibility)
  RETURNING id INTO v_group_id;

  INSERT INTO public.study_group_members (group_id, user_id, role)
  VALUES (v_group_id, v_uid, 'owner');

  RETURN v_group_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_study_group(text, text, text) TO authenticated;

-- FROM 2026101004_challenges_and_leaderboard.sql
-- =============================================================================
-- Migration: 20261010_04_challenges_and_leaderboard
--
-- The rule this migration exists to enforce:
--
--   Points must never reflect a claim. Every point is awarded by a function
--   that first re-derives the underlying fact from the user's own rows.
--   A client that calls these functions cannot inflate a score, because the
--   client supplies no numbers at all — only ids.
--
-- All functions are SECURITY DEFINER and re-verify the caller's privileges,
-- since SECURITY DEFINER bypasses RLS.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Challenge creation and membership
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.create_group_challenge(
  p_group_id     uuid,
  p_title        text,
  p_description  text DEFAULT NULL,
  p_rules        text DEFAULT NULL,
  p_challenge_type text,
  p_target_count integer,
  p_starts_at    timestamptz DEFAULT now(),
  p_ends_at      timestamptz DEFAULT timestamptz 'now() + interval '7 days',
  p_bonus_points integer DEFAULT 25
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_id  uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_group_role(p_group_id, v_uid, ARRAY['owner', 'admin']::text[]) THEN
    RAISE EXCEPTION 'Only a group owner or admin can create challenges' USING ERRCODE = '42501';
  END IF;

  IF p_challenge_type NOT IN ('sessions', 'phase', 'project', 'revision', 'consistency') THEN
    RAISE EXCEPTION 'Invalid challenge type' USING ERRCODE = '22023';
  END IF;

  IF btrim(p_title) IS NULL OR char_length(btrim(p_title)) < 1 THEN
    RAISE EXCEPTION 'Title is required' USING ERRCODE = '22023';
  END IF;

  -- target_count means different things per type. For a 'phase' challenge it
  -- is the phase position, so it must be a real phase number.
  IF p_target_count < 1 THEN
    RAISE EXCEPTION 'Target count must be at least 1' USING ERRCODE = '22023';
  END IF;

  IF p_challenge_type = 'phase' AND NOT EXISTS (
    SELECT 1 FROM public.curriculum_phases WHERE position = p_target_count
  ) THEN
    RAISE EXCEPTION 'No curriculum phase with that position' USING ERRCODE = '22023';
  END IF;

  IF p_ends_at <= p_starts_at THEN
    RAISE EXCEPTION 'Challenge end must be after its start' USING ERRCODE = '22023';
  END IF;

  IF p_bonus_points < 0 OR p_bonus_points > 1000 THEN
    RAISE EXCEPTION 'Bonus points must be between 0 and 1000' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.group_challenges
    (group_id, created_by, title, description, rules, challenge_type,
     target_count, starts_at, ends_at, bonus_points)
  VALUES
    (p_group_id, v_uid, btrim(p_title), p_description, p_rules, p_challenge_type,
     p_target_count, p_starts_at, p_ends_at, p_bonus_points)
  RETURNING id INTO v_id;

  -- The creator joins automatically.
  INSERT INTO public.challenge_participants (challenge_id, user_id) VALUES (v_id, v_uid);

  RETURN v_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_group_challenge(
  uuid, text, text, text, text, integer, timestamptz, timestamptz, integer
) TO authenticated;

CREATE OR REPLACE FUNCTION public.join_challenge(p_challenge_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid       uuid := auth.uid();
  v_group     uuid;
  v_ends_at   timestamptz;
  v_completed boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT group_id, ends_at INTO v_group, v_ends_at
  FROM public.group_challenges WHERE id = p_challenge_id;

  IF v_group IS NULL THEN
    RAISE EXCEPTION 'Challenge not found' USING ERRCODE = '22023';
  END IF;

  -- Must be a member of the owning group.
  IF NOT public.is_group_member(v_group, v_uid) THEN
    RAISE EXCEPTION 'You must be a member of this group to join its challenges'
      USING ERRCODE = '42501';
  END IF;

  IF v_ends_at < now() THEN
    RAISE EXCEPTION 'This challenge has already ended' USING ERRCODE = '22023';
  END IF;

  -- Never let someone re-join a completed challenge to re-trigger points.
  SELECT completed INTO v_completed
  FROM public.challenge_participants
  WHERE challenge_id = p_challenge_id AND user_id = v_uid;

  IF v_completed THEN
    RAISE EXCEPTION 'You already completed this challenge' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.challenge_participants (challenge_id, user_id)
  VALUES (p_challenge_id, v_uid)
  ON CONFLICT (challenge_id, user_id) DO NOTHING;
END;
$$;

GRANT EXECUTE ON FUNCTION public.join_challenge(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.leave_challenge(p_challenge_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  DELETE FROM public.challenge_participants
  WHERE challenge_id = p_challenge_id AND user_id = v_uid;
END;
$$;

GRANT EXECUTE ON FUNCTION public.leave_challenge(uuid) TO authenticated;

-- -----------------------------------------------------------------------------
-- Progress computation
--
-- This is the heart of the anti-gaming design: the caller passes no numbers.
-- Progress is derived from rows the caller already owns.
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.compute_challenge_progress(p_challenge_id uuid, p_user_id uuid)
RETURNS integer
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
-- Authorization: the caller must be the user themselves, or an owner/admin of
-- the group containing this challenge.
IF NOT EXISTS (
    SELECT 1 FROM public.group_challenges gc
    JOIN public.study_group_members m ON m.group_id = gc.group_id
    WHERE gc.id = p_challenge_id
      AND m.user_id = p_user_id
      AND public.has_group_role(gc.group_id, p_user_id, ARRAY['owner', 'admin']::text[])
  ) THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.auth.users WHERE id = p_user_id
    ) THEN
      RAISE EXCEPTION 'User not found' USING ERRCODE = '22023';
    END IF;
    IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
      RAISE EXCEPTION 'Permission denied' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- [rest of the function was already here, I need to preserve it]
DECLARE
  c        public.group_challenges%ROWTYPE;
  v_result integer := 0;
BEGIN
  SELECT * INTO c FROM public.group_challenges WHERE id = p_challenge_id;
  IF c.id IS NULL THEN
    RETURN 0;
  END IF;

  -- 'sessions': completed focus sessions inside the challenge window.
  IF c.challenge_type = 'sessions' THEN
    SELECT count(*)::integer INTO v_result
    FROM public.study_sessions s
    WHERE s.user_id = p_user_id
      AND s.duration_seconds >= 60              -- ignore accidental taps
      AND s.started_at >= c.starts_at
      AND s.started_at <= c.ends_at;

  -- 'phase': 1 when every day of the target phase is completed.
  ELSIF c.challenge_type = 'phase' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.curriculum_days d
      WHERE d.day_number BETWEEN
            (SELECT start_day FROM public.curriculum_phases WHERE position = c.target_count)
            AND (SELECT end_day FROM public.curriculum_phases WHERE position = c.target_count)
        AND NOT EXISTS (
          SELECT 1 FROM public.user_day_progress udp
          WHERE udp.user_id = p_user_id
            AND udp.day_id = d.id
            AND udp.status = 'completed'
        )
    ) THEN
      v_result := 1;
    ELSE
      v_result := 0;
    END IF;

  -- 'project': projects moved to completed inside the window.
  ELSIF c.challenge_type = 'project' THEN
    SELECT count(*)::integer INTO v_result
    FROM public.user_projects p
    WHERE p.user_id = p_user_id
      AND p.status = 'completed'
      AND p.updated_at >= c.starts_at
      AND p.updated_at <= c.ends_at;

  -- 'revision': submitted weekly reviews inside the window.
  ELSIF c.challenge_type = 'revision' THEN
    SELECT count(*)::integer INTO v_result
    FROM public.weekly_reviews w
    WHERE w.user_id = p_user_id
      AND w.submitted_at IS NOT NULL
      AND w.submitted_at >= c.starts_at
      AND w.submitted_at <= c.ends_at;

  -- 'consistency': longest run of consecutive days with a completion inside
  -- the window. Computed over distinct local dates.
  ELSIF c.challenge_type = 'consistency' THEN
    WITH days AS (
      SELECT DISTINCT (udp.completed_at AT TIME ZONE 'UTC')::date AS d
      FROM public.user_day_progress udp
      WHERE udp.user_id = p_user_id
        AND udp.status = 'completed'
        AND udp.completed_at IS NOT NULL
        AND udp.completed_at >= c.starts_at
        AND udp.completed_at <= c.ends_at
    ), ordered AS (
      SELECT d, d - (row_number() OVER (ORDER BY d))::int AS grp FROM days
    ), runs AS (
      SELECT grp, count(*)::int AS len FROM ordered GROUP BY grp
    )
    SELECT coalesce(max(len), 0)::integer INTO v_result FROM runs;

  END IF;

  -- Never report progress beyond the target, so the UI can never show
  -- 12/10 for a "10 sessions" challenge.
  RETURN least(v_result, c.target_count);
END;
$$;

GRANT EXECUTE ON FUNCTION public.compute_challenge_progress(uuid, uuid) TO authenticated;

-- Refresh the caller's own participation rows, and award points exactly once
-- when a challenge is genuinely complete. Also attempts idempotent ledger insert
-- so points are not lost if the UI closes during completion.
CREATE OR REPLACE FUNCTION public.refresh_my_challenge_progress()
RETURNS TABLE (challenge_id uuid, progress integer, completed boolean, just_completed boolean)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  RETURN QUERY
  WITH computed AS (
    SELECT
      cp.id            AS cid,
      cp.completed     AS was_complete,
      public.compute_challenge_progress(cp.id, v_uid) AS now_progress,
      gc.target_count  AS target,
      gc.bonus_points  AS bonus
    FROM public.challenge_participants cp
    JOIN public.group_challenges gc ON gc.id = cp.challenge_id
    WHERE cp.user_id = v_uid
      -- Only inside an active window, and before it closes.
      AND gc.starts_at <= now()
      AND gc.ends_at >= now()
  ),
  updated AS (
    UPDATE public.challenge_participants p
    SET progress = c.now_progress,
        completed = (c.now_progress >= c.target),
        completed_at = CASE
          WHEN (c.now_progress >= c.target) THEN coalesce(p.completed_at, now())
          ELSE NULL
        END
    FROM computed c
    WHERE p.id = c.cid
    RETURNING
      p.challenge_id,
      p.progress,
      p.completed,
      -- True only on the transition from incomplete to complete.
      (p.completed AND NOT c.was_complete) AS just_completed
  )
  INSERT INTO public.point_ledger (user_id, reason, points, ref_type, ref_id)
  SELECT v_uid, 'challenge_completed', bonus, 'challenge', cid
  FROM updated
  WHERE just_completed = true
  ON CONFLICT DO NOTHING;

  RETURN QUERY
  SELECT challenge_id, progress, completed, just_completed FROM updated;
END;
$$;

GRANT EXECUTE ON FUNCTION public.refresh_my_challenge_progress() TO authenticated;

CREATE OR REPLACE FUNCTION public.award_challenge_points(p_challenge_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_completed boolean;
  v_bonus    integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT completed INTO v_completed
  FROM public.challenge_participants
  WHERE challenge_id = p_challenge_id AND user_id = v_uid;

  IF v_completed IS NOT TRUE THEN
    RAISE EXCEPTION 'Challenge is not complete' USING ERRCODE = '22023';
  END IF;

  SELECT bonus_points INTO v_bonus
  FROM public.group_challenges WHERE id = p_challenge_id;

  -- ON CONFLICT DO NOTHING makes this safe to call repeatedly: the ledger's
  -- unique index on (user_id, reason, ref_type, ref_id) blocks a second award.
  INSERT INTO public.point_ledger (user_id, reason, points, ref_type, ref_id)
  VALUES (v_uid, 'challenge_completed', v_bonus, 'challenge', p_challenge_id)
  ON CONFLICT DO NOTHING;

  RETURN v_bonus;
END;
$$;

GRANT EXECUTE ON FUNCTION public.award_challenge_points(uuid) TO authenticated;

-- -----------------------------------------------------------------------------
-- Achievements
--
-- Awarded by re-checking the underlying condition, never by client request.
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.sync_my_achievements()
RETURNS TABLE (code text, title_en text, title_ar text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_days integer;
  v_projects integer;
  v_deployed integer;
  v_reviews integer;
  v_sessions integer;
  v_first_phase integer;
  v_streak integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT count(*)::int INTO v_days
  FROM public.user_day_progress WHERE user_id = v_uid AND status = 'completed';

  SELECT count(*)::int INTO v_projects
  FROM public.user_projects WHERE user_id = v_uid AND status = 'completed';

  SELECT count(*)::int INTO v_deployed
  FROM public.user_projects WHERE user_id = v_uid AND live_url IS NOT NULL;

  SELECT count(*)::int INTO v_reviews
  FROM public.weekly_reviews WHERE user_id = v_uid AND submitted_at IS NOT NULL;

  SELECT count(*)::int INTO v_sessions
  FROM public.study_sessions WHERE user_id = v_uid AND duration_seconds >= 300;

  -- A phase counts as complete when every day in it is completed.
  SELECT count(*)::int INTO v_first_phase FROM (
    SELECT ph.position
    FROM public.curriculum_phases ph
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.curriculum_days d
      WHERE d.day_number BETWEEN ph.start_day AND ph.end_day
        AND NOT EXISTS (
          SELECT 1 FROM public.user_day_progress udp
          WHERE udp.user_id = v_uid AND udp.day_id = d.id AND udp.status = 'completed'
        )
    )
  ) s;

  -- Longest run of consecutive calendar days with a completion.
  WITH days AS (
    SELECT DISTINCT (completed_at AT TIME ZONE 'UTC')::date AS d
    FROM public.user_day_progress
    WHERE user_id = v_uid AND status = 'completed' AND completed_at IS NOT NULL
  ), ordered AS (
    SELECT d, d - (row_number() OVER (ORDER BY d))::int AS grp FROM days
  ), runs AS (
    SELECT grp, count(*)::int AS len FROM ordered GROUP BY grp
  )
  SELECT coalesce(max(len), 0)::int INTO v_streak FROM runs;

  INSERT INTO public.user_achievements (user_id, achievement_id)
  SELECT v_uid, a.id
  FROM public.achievements a
  WHERE NOT EXISTS (
          SELECT 1 FROM public.user_achievements ua
          WHERE ua.user_id = v_uid AND ua.achievement_id = a.id
        )
    AND CASE a.criteria ->> 'type'
      WHEN 'days_completed'   THEN v_days     >= (a.criteria ->> 'threshold')::int
      WHEN 'projects_completed' THEN v_projects >= (a.criteria ->> 'threshold')::int
      WHEN 'deployments'      THEN v_deployed >= (a.criteria ->> 'threshold')::int
      WHEN 'reviews'          THEN v_reviews   >= (a.criteria ->> 'threshold')::int
      WHEN 'sessions'         THEN v_sessions  >= (a.criteria ->> 'threshold')::int
      WHEN 'phases_completed' THEN v_first_phase >= (a.criteria ->> 'threshold')::int
      WHEN 'streak_days'      THEN v_streak     >= (a.criteria ->> 'threshold')::int
      ELSE false
    END
  ON CONFLICT DO NOTHING;

  RETURN QUERY
    SELECT a.code, a.title_en, a.title_ar
    FROM public.user_achievements ua
    JOIN public.achievements a ON a.id = ua.achievement_id
    WHERE ua.user_id = v_uid
    ORDER BY ua.earned_at DESC;
END;
$$;

GRANT EXECUTE ON FUNCTION public.sync_my_achievements() TO authenticated;

-- -----------------------------------------------------------------------------
-- Leaderboard
--
-- Aggregated in the database so that (a) no other user's private rows are sent
-- to the client, and (b) users who opted out of rankings never appear.
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.leaderboard(
  p_period    text DEFAULT 'all',
  p_group_id  uuid DEFAULT NULL
)
RETURNS TABLE (
  rank        integer,
  user_id     uuid,
  username    text,
  display_name text,
  points      integer
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_since timestamptz;
  v_uid   uuid := auth.uid();
BEGIN
  IF p_period = 'week' THEN
    v_since := date_trunc('week', now());
  ELSIF p_period = 'month' THEN
    v_since := date_trunc('month', now());
  ELSIF p_period = 'all' THEN
    v_since := NULL;
  ELSE
    RAISE EXCEPTION 'Invalid period' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH totals AS (
    SELECT
      pl.user_id,
      sum(pl.points)::int AS pts
    FROM public.point_ledger pl
    WHERE (v_since IS NULL OR pl.created_at >= v_since)
-- Group scoping: only members of the requested group can view its leaderboard.
  AND (
    p_group_id IS NULL
    OR (public.is_group_member(p_group_id, auth.uid()) AND EXISTS (
      SELECT 1 FROM public.study_group_members m
      WHERE m.group_id = p_group_id
        AND m.user_id = pl.user_id
    ))
  )
      -- Opt-out is honoured here, so an opted-out user never reaches the client.
      AND NOT EXISTS (
        SELECT 1 FROM public.user_privacy_settings s
        WHERE s.user_id = pl.user_id AND s.hidden_from_leaderboard = true
      )
    GROUP BY pl.user_id
  )
  SELECT
    (row_number() OVER (ORDER BY t.pts DESC, t.user_id) - 1)::int,
    t.user_id,
    p.username,
    p.display_name,
    t.pts
  FROM totals t
  JOIN public.profiles p ON p.id = t.user_id
  ORDER BY t.pts DESC, t.user_id
  LIMIT 100;
END;
$$;

GRANT EXECUTE ON FUNCTION public.leaderboard(text, uuid) TO authenticated;

-- -----------------------------------------------------------------------------
-- User's own points summary
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.my_points()
RETURNS TABLE (total integer, by_reason jsonb)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  RETURN QUERY
  SELECT
    coalesce(sum(points), 0)::int,
    coalesce(jsonb_object_agg(reason, total), '{}'::jsonb)
  FROM (
    SELECT reason, sum(points)::int AS total
    FROM public.point_ledger
    WHERE user_id = v_uid
    GROUP BY reason
  ) s;
END;
$$;

GRANT EXECUTE ON FUNCTION public.my_points() TO authenticated;

