 VALUES ('67c57cea-90a7-543a-8f95-523803cfa125', 'capstone', 10, 'Capstone MVP', 'المشروع التخرّجي',
         'Scope, requirements, architecture, database, auth, features, tests, docs.', 'النطاق والمتطلبات والبنية وقاعدة البيانات والمصادقة والميزات والاختبارات والتوثيق.', 271, 300,
         'A working capstone MVP.', 'نسخة أولية عاملة من المشروع التخرّجي.')
