 VALUES ('6c31afc3-119b-59c9-b6fd-ee8d95404642', 'portfolio-career', 12, 'Portfolio & Career Preparation', 'المعرض المهني والاستعداد للوظيفة',
         'Portfolio, READMEs, technical writing, and interview practice.', 'المعرض المهني وملفات README والكتابة التقنية والتدرّب على المقابلات.', 331, 365,
