 VALUES ('b929e649-4f24-56bf-b375-b90069ae5076', 125, 'ef71b849-2224-52fd-8a8a-37520256275e',
         'Database Review and Consolidation', 'Database Review and Consolidation', 'Review',
         'Re-read the schema you built and fix weaknesses: missing constraints, missing indexes, unclear naming.', 'Re-read the schema you built and fix weaknesses: missing constraints, missing indexes, unclear naming.',
